  Definition shc_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (E PC lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk,
      ms' = MS (mkR (Z_to_bv 64 (E + 36)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2
                    (Z_to_bv 64 PC) (Z_to_bv 64 0) (Z_to_bv 64 (shc_size E)) a1 a2 a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp); (PC, PC + 8)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells usegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra]
      /\ rw_cells usegs m' PC [C8 (Z_to_bv 64 0)].
