  Definition msi_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (R lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk junk',
      ms' = MS (mkR (Z_to_bv 64 P_MSI_RET1) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                    (Z_to_bv 64 (bv_unsigned sp + -48)) (Z_to_bv 64 R) (Z_to_bv 64 (bv_unsigned sp + -48)) (Z_to_bv 64 0) (Z_to_bv 64 0) a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_SHCOUNT_CTOR_IMPL) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -64)
      /\ rw_cells usegs m' (bv_unsigned sp + -64) [CB 8 junk; C8 (Z_to_bv 64 0)]
      /\ rw_cells usegs m' (bv_unsigned sp + -48) [CB 8 junk']
      /\ rw_cells usegs m' (bv_unsigned sp + -40) [C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

