      (F : bvmap 5 word) fc (m : mem) (R lo : Z),
    stk usegs m lo (bv_unsigned sp) -> lo + 64 <= bv_unsigned sp ->
    mem_inv usegs m ->
    evt usegs (msi_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R lo m)
