  (* [comment removed for export] *)
  Definition msi_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (R q lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp); (q, q + 96); (R, R + 16)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' q (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 1) j7)
      /\ rw_cells usegs m' (q + 32) [CB 64 (zeros 64)]
      /\ rw_cells usegs m' R [C8 (Z_to_bv 64 (q + 32)); C8 (Z_to_bv 64 q)].

  Lemma msi_segB : forall sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (rax s2x s3x ra s0 s1 : word) (F : bvmap 5 word) fc (m : mem) (R q lo : Z) (j7 junk jr j0 : list byte),
    rw_cells usegs m (bv_unsigned sp + -64) [CB 8 j0; C8 (Z_to_bv 64 0)] ->
    rw_cells usegs m (bv_unsigned sp + -48) [C8 (Z_to_bv 64 q)] ->
    rw_cells usegs m (bv_unsigned sp + -40) [C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells usegs m q (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 0) j7) ->
    rw_cells usegs m (q + 32) [CB 64 junk] ->
    rw_cells usegs m R [CB 16 jr] ->
    XStatics m ->
    stk usegs m lo (bv_unsigned sp + -64) -> lo + 96 <= bv_unsigned sp -> hceil <= lo ->
    0 < q -> q mod 16 = 0 -> q + 96 <= lo -> R + 16 <= lo -> (R + 16 <= q \/ q + 96 <= R) -> 0 < R ->
    mem_inv usegs m ->
    evt usegs (msi_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R q lo j7 m)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
               (Z_to_bv 64 (bv_unsigned sp + -48)) (Z_to_bv 64 R) (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7
               s2x s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_MSI_RET1) fc None m (seg_rom usegs)).
