(* [comment removed for export] *)
Definition ANYEX_COPY_STACK : Z := 16.

Definition anyex_copy_post (ra sp gp tp s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (D S ioc lo : Z) (jd : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 m' jm,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz D) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (D, D + 48)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' D [C8 (wz ioc); CB 16 jm; C8 (wz T_ANYEX_OBJECT_FNS); C8 (wz D); C8 (wz T_ANYEX_TARGET_FNS)].

Definition anyex_copy_stmt : Prop :=
  forall (D S ioc lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (jd j16 : list byte),
  rw_cells usegs m D [CB 48 jd] -> ro_cells usegs m S (AnyExecCells S ioc j16) -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) -> lo + ANYEX_COPY_STACK <= bv_unsigned sp -> hceil <= lo ->
  (D + 48 <= lo \/ bv_unsigned sp <= D) -> (S + 56 <= lo \/ bv_unsigned sp <= S) -> (S + 56 <= D \/ D + 48 <= S) ->
  (D + 48 <= 0x10000 \/ 0xb8000 <= D) ->
  0 <= ioc < 2^64 -> 0 < S ->
  mem_inv usegs m ->
  evt usegs (anyex_copy_post ra sp gp tp s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc D S ioc lo jd m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz D) (wz S) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ANYEX_COPY) fc None m (seg_rom usegs)).

